class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is PurchasePathsMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    } else if (value is ConfigureRequest) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    } else if (value is CustomerMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    } else if (value is PurchaseRequest) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    } else if (value is PurchaseOptionMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is PurchaseSessionMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is PurchaseFailureMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is BillingFailureMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is PurchaseOutcomeMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is PurchaseEventMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is ReturnLinkResultMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is EntitlementItemMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is EntitlementsMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return PurchasePathsMessage.decode(readValue(buffer)!);
      case 130:
        return ConfigureRequest.decode(readValue(buffer)!);
      case 131:
        return CustomerMessage.decode(readValue(buffer)!);
      case 132:
        return PurchaseRequest.decode(readValue(buffer)!);
      case 133:
        return PurchaseOptionMessage.decode(readValue(buffer)!);
      case 134:
        return PurchaseSessionMessage.decode(readValue(buffer)!);
      case 135:
        return PurchaseFailureMessage.decode(readValue(buffer)!);
      case 136:
        return BillingFailureMessage.decode(readValue(buffer)!);
      case 137:
        return PurchaseOutcomeMessage.decode(readValue(buffer)!);
      case 138:
        return PurchaseEventMessage.decode(readValue(buffer)!);
      case 139:
        return ReturnLinkResultMessage.decode(readValue(buffer)!);
      case 140:
        return EntitlementItemMessage.decode(readValue(buffer)!);
      case 141:
        return EntitlementsMessage.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

