/// Events from the native SDKs to Dart.
/// Purchases that moved outside a `purchase` call.
///
/// Returns a broadcast [Stream] of events from the `purchaseEvents` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<PurchaseEventMessage> purchaseEvents({String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel purchaseEventsChannel = EventChannel(
    'dev.flutter.pigeon.india_subscriptions.PurchaseStreams.purchaseEvents$instanceName',
    pigeonMethodCodec,
  );
  return purchaseEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as PurchaseEventMessage;
  });
}

